import json,pathlib
p=pathlib.Path(__file__).parent.parent;s=p.name
cases=[
('clinic','My friend, Orin Vell, offered to accompany me to the appointment. I have had headaches on four mornings this week, but none woke me during the night. I have not tried any new medicine. I would like to make a clear list of what to mention and keep the timing accurate.\n\nSeparately, my monthly rent is 810 euros and I need to compare it with last year.', 'Orin Vell','HEALTH','I have had headaches on four mornings this week, but none woke me during the night.','FINANCIAL','my monthly rent is 810 euros','\n\nSeparately, my monthly rent is 810 euros and I need to compare it with last year.','Help me prepare a clinician note about symptoms; omit the separate rent note.','Help me organise the rent comparison; omit the unrelated symptom details.', ['I have had headaches on four mornings this week, but none woke me during the night.','I have not tried any new medicine.'],['my monthly rent is 810 euros']),
('travel','My sister, Zela Porr, is helping me organise a trip by train. The train leaves at 09:20 and the connection allows only twelve minutes; I want to ask the operator whether that is enough time. We will travel with one small suitcase each and prefer a direct service if available.\n\nMy savings balance is 3,250 euros and I am considering changing banks.', 'Zela Porr','FINANCIAL','My savings balance is 3,250 euros','FINANCIAL','My savings balance is 3,250 euros','\n\nMy savings balance is 3,250 euros and I am considering changing banks.','Draft a question to the train operator; the bank note is unrelated.','Summarise the savings note for my personal budget; the travel paragraph is unrelated.', ['The train leaves at 09:20 and the connection allows only twelve minutes; I want to ask the operator whether that is enough time.','We will travel with one small suitcase each and prefer a direct service if available.'],['My savings balance is 3,250 euros']),
('work','My neighbour, Tavie Renn, offered to help me with a household repair. The kitchen tap drips every few seconds even when fully closed. I have turned off the local valve, but I have not dismantled the fitting. Please retain these details when preparing a question for a plumber.\n\nMy annual salary is 31,500 euros and I am considering a savings plan.', 'Tavie Renn','FINANCIAL','My annual salary is 31,500 euros','FINANCIAL','My annual salary is 31,500 euros','\n\nMy annual salary is 31,500 euros and I am considering a savings plan.','Draft a question for a plumber; omit the unrelated financial paragraph.','Summarise the salary and savings note; the repair is unrelated.', ['The kitchen tap drips every few seconds even when fully closed.','I have turned off the local valve, but I have not dismantled the fitting.'],['My annual salary is 31,500 euros']),
('sales','Our account manager, Leda Fenn, met the prospective customer yesterday. The customer requested a shorter onboarding checklist and asked whether training can be remote. We should respond professionally, but must not promise a delivery date before operations confirms capacity.\n\nThe confidential draft price is 64,800 euros and the quote has not been approved for external disclosure.', 'Leda Fenn','FINANCIAL','64,800 euros','FINANCIAL','64,800 euros','\n\nThe confidential draft price is 64,800 euros and the quote has not been approved for external disclosure.','Draft a generic onboarding follow-up using an external assistant; omit the separate pricing note.','Explain the limitations of assessing the confidential draft price using an external assistant, without revealing the value.', ['The customer requested a shorter onboarding checklist and asked whether training can be remote.','We should respond professionally, but must not promise a delivery date before operations confirms capacity.'],['The confidential draft price is','the quote has not been approved for external disclosure.']),
('ops','Our coordinator, Fenna Rusk, reported that the sample delivery arrived one day late. Two cartons were intact, but the third had a torn seal. Ask the supplier for inspection instructions before anyone uses the contents, and do not state that the contents were damaged.\n\nA confidential internal budget allocation is 23,400 euros for this delivery programme.', 'Fenna Rusk','FINANCIAL','23,400 euros','FINANCIAL','23,400 euros','\n\nA confidential internal budget allocation is 23,400 euros for this delivery programme.','Draft a generic supplier question about the delivery; omit the separate budget.','Describe the limits of analysing the confidential budget with an external assistant, without revealing the amount.', ['Two cartons were intact, but the third had a torn seal.','Ask the supplier for inspection instructions before anyone uses the contents, and do not state that the contents were damaged.'],['A confidential internal budget allocation is','for this delivery programme.'])]
records=[];notes=[]
for slug,text,name,l1,q1,l2,q2,drop,t1,t2,f1,f2 in cases:
 # Detection is identical across variants; annotate the protected paragraph value and the private name.
 entities=[dict(id='m1',entity_id='person',quote=name,label='PERSON'),dict(id='m2',entity_id='sensitive',quote=q2,label=l2)]
 for version in (1,2):
  rid=f'{s}:{slug}-{version}'; task=(t1,t2)[version-1]
  if version==1:
   ds=[dict(kind='entity',target_id='m1',entity_id='person',quote=name,label='PERSON',action='ALIAS',relevance='unnecessary'),dict(kind='section',quote=drop,label=l2,action='DROP',relevance='unnecessary',reason='The separate sensitive paragraph is unrelated to the requested task.')]
   out=text.replace(name,'[PERSON_1]').replace(drop,'');facts=f1
  else:
   # Keep the general context and alter the sensitive fact according to its disclosure boundary.
   a='PLACEHOLDER' if slug in ('sales','ops') else 'KEEP'
   ds=[dict(kind='entity',target_id='m1',entity_id='person',quote=name,label='PERSON',action='ALIAS',relevance='unnecessary'),dict(kind='entity',target_id='m2',entity_id='sensitive',quote=q2,label=l2,action=a,relevance='essential')]
   if a=='PLACEHOLDER': ds[1]['reason']='The exact internal amount is confidential; numerical analysis is unavailable after protection.'
   out=text.replace(name,'[PERSON_1]')
   if a=='PLACEHOLDER':out=out.replace(q2,'[FINANCIAL]')
   facts=f2
  records.append(dict(schema_version=2,shard_id=s,id=rid,family_id=f'{s}:{slug}-family',persona_id=f'{s}:{slug}-persona',source_id=f'{s}:{slug}-source',template_id=f'{s}:{slug}-template',split='dev',language='en',input_kind='message',task=task,text=text,entities=entities,decisions=ds,required_facts=[{'quote':q} for q in facts],approved_output=out,provenance={'synthetic':True,'human_audited':False,'generator_id':f'{s}:generator','generator_model':'gpt-6.1-terra'},review={'status':'pending'}))
  deps=[{'claim':q,'source_quotes':[q],'disclosable':True} for q in facts]
  if version==2 and slug in ('sales','ops'):deps.append({'claim':'Exact confidential amount','source_quotes':[q2],'disclosable':False,'utility_limit':'Exact numerical analysis cannot be performed.'})
  notes.append({'record_id':rid,'dependencies':deps,'group_relationship':'Two tasks use the identical source, persona and entity annotations.'})
(p/'draft-02.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))
(p/'author-notes-02.jsonl').write_text(''.join(json.dumps(n,ensure_ascii=False)+'\n' for n in notes))
